CREATE TABLE events (
    id      INTEGER PRIMARY KEY,
    user_id INTEGER NOT NULL,
    type    TEXT    NOT NULL,
    ts      TEXT    NOT NULL
);
INSERT INTO events VALUES (1, 42, 'login',    '2024-01-01 08:00');
INSERT INTO events VALUES (2,  7, 'click',    '2024-01-01 09:15');
INSERT INTO events VALUES (3, 42, 'purchase', '2024-01-01 10:30');
INSERT INTO events VALUES (4, 42, 'logout',   '2024-01-01 11:00');

CREATE INDEX idx_events_user ON events(user_id);

SELECT type, ts
FROM   events
WHERE  user_id = 42
ORDER  BY ts;
